package br.com.loja.checkout.dominio;

import java.math.BigDecimal;
import java.util.List;

/** Itens do pedido já validados, com os totais usados pelas demais regras. */
public record Carrinho(List<Item> itens) {

    public Carrinho {
        itens = List.copyOf(itens);
    }

    /** Soma dos produtos, arredondada para centavos. */
    public BigDecimal subtotalProdutos() {
        return Dinheiro.centavos(itens.stream().map(Item::valorTotal).reduce(BigDecimal.ZERO, BigDecimal::add));
    }

    /** Peso total do pedido, sem arredondamento. */
    public BigDecimal pesoTotalKg() {
        return itens.stream().map(Item::pesoTotal).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
EOF
cat > dominio/Catalogo.java <<'EOF'
package br.com.loja.checkout.dominio;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;
import java.util.stream.Collectors;

/** Conjunto de opções (entregas, cupons, níveis...) localizadas pelo código. */
public class Catalogo<T> {

    private final Map<String, T> porCodigo;

    public Catalogo(List<T> opcoes, Function<T, String> codigo) {
        this.porCodigo = opcoes.stream().collect(Collectors.toUnmodifiableMap(codigo, Function.identity()));
    }

    public Optional<T> buscar(String codigo) {
        return codigo == null ? Optional.empty() : Optional.ofNullable(porCodigo.get(codigo));
    }
}
EOF

